from _dsl import *
ORDER = 27.5
DATA = '0 0 2 0 1 II\n1 0 2 0 1.5 II\n3 0 2 0 2 III\n10 0 4 0 2 II\n12 0 4 0 2.125 II\n15 0 4 0 2.25 II\n'
READ = "rows=[]\nfor line in open('particles.txt'):\n    x,y,vx,vy,m,kind=line.split()\n    x,y,vx,vy,m=map(float,(x,y,vx,vy,m))\n    rows.append((x,y,m*(vx*vx+vy*vy)/2,kind))\n"
SOL = READ + "groups = [[p for p in rows if p[2]<10], [p for p in rows if p[2]>=10]]\ncenters=[min(g,key=lambda p:sum(abs(p[2]-q[2]) for q in g)) for g in groups]\nfrom math import hypot\nq1=max(hypot(p[0]-q[0],p[1]-q[1]) for g in groups for p in g for q in g if p[3]==q[3]=='II')\nq2=max(p[2] for p in centers)\nprint(int(q1*10000), int(q2*10000))"
MODULE = module('m32', 'Анализ признаков: формат 2027', 'Σ', 'Учебный переход к №27: кластеризуем по энергии, расстояние считаем по координатам; ответ из двух чисел.', [
    level('Признак и метрика', 'Не подменять условие готовым шаблоном кластеризации.', [
        txt('Разные величины в одной задаче', p('В проекте демоверсии-2027 кластеризация использует кинетическую энергию m×(Vx²+Vy²)/2. Центр минимизирует сумму модулей разностей энергий, а отдельный вопрос может использовать расстояния по координатам.', 'Наша маленькая задача — подготовительное упражнение. Группы заданы явно; метод для больших данных выбирайте по ограничениям конкретного задания.')),
        code('Чтение шести столбцов', READ+"\nprint([p[2] for p in rows])", files={'particles.txt':DATA}, cond=p('Поля: x y Vx Vy m признак. В файле точки как десятичный разделитель; если будут запятые, замените их при чтении.')),
    ], [
        task('max_energy', 'Максимальная энергия', p('Для файла particles.txt найди максимальную кинетическую энергию.'), READ+'\nprint(max(p[2] for p in rows))', files={'particles.txt':DATA}, hint='Координаты x,y в формулу энергии не входят.'),
        task('two_outputs', 'Два результата', p('Две группы: энергия меньше 10 и энергия не меньше 10. Центр — частица с минимальной суммой модулей разностей энергий внутри группы. Q1 — наибольшее расстояние между частицами с признаком II одной группы; Q2 — наибольшая энергия центра. Выведи целые части Q1×10000 и Q2×10000 одной строкой.'), SOL, files={'particles.txt':DATA}, hint='Сначала раздели частицы, потом независимо вычисляй центр по энергии и расстояния по координатам.'),
    ], need=2),
], n=27)
